describe('Checkout Form Required Field Validation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display error when postal code is missing during checkout', () => {
    // Login with standard user
    cy.get('[name="user-name"]').type('standard_user');
    cy.get('[name="password"]').type('secret_sauce');
    cy.get('[name="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart and checkout
    cy.get('[data-test="shopping-cart-link"]').click();
    cy.get('[data-test="checkout"]').click();

    // Fill only first and last name
    cy.get('[name="firstName"]').type('Saif');
    cy.get('[name="lastName"]').type('Afzal');

    // Attempt to continue without postal code
    cy.get('[name="continue"]').click();

    // Verify error message appears
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Postal Code is required');

    // Verify user is still on checkout page
    cy.url().should('include', '/checkout');
  });

  it('should successfully submit checkout form when all required fields are filled', () => {
    // Login with standard user
    cy.get('[name="user-name"]').type('standard_user');
    cy.get('[name="password"]').type('secret_sauce');
    cy.get('[name="login-button"]').click();

    // Add backpack to cart
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart and checkout
    cy.get('[data-test="shopping-cart-link"]').click();
    cy.get('[data-test="checkout"]').click();

    // Fill all required fields
    cy.get('[name="firstName"]').type('Saif');
    cy.get('[name="lastName"]').type('Afzal');
    cy.get('[name="postalCode"]').type('12345');

    // Click continue and verify success
    cy.get('[name="continue"]').click();

    // Verify success message or next step is reached
    cy.get('[data-testid="error"]').should('not.exist');
    cy.get('[data-testid="finish-checkout-button"]').should('be.visible');
    cy.get('[data-testid="finish-checkout-button"]').click();

    // Verify order confirmation page
    cy.url().should('include', '/checkout-complete');
    cy.get('[data-testid="order-confirmation-title"]').should('contain', 'Thank You');
  });
});
